async ({ delivery: { commit }, gh: { prCreate } }, p: { body: string }) => {
  const c = await commit({ files: [".github/workflows/pi-assistant.yml"], message: "ci(pi-assistant): install locked dependencies before pi runs\n\nRefs #379", push: true });
